@Service public class ProposalAuthorizationService {private final JdbcTemplate jdbc;
private final ObjectMapper mapper;
private final OstrisWireCodec wire = new OstrisWireCodec();
private final CommunityRepository communities;
private final JournalCommitService journal;
public ProposalAuthorizationService(JdbcTemplate jdbc, ObjectMapper mapper, CommunityRepository communities, JournalCommitService journal) {this.jdbc = jdbc; this.mapper = mapper; this.communities = communities; this.journal = journal;}
@Transactional public ProposalView propose(CommitTransactionCommand c) {this.validateRestitutionProposal(c); List<TransactionEntry> entries = this.entries(c); TransactionValidator.validateBalanced(entries); ObjectNode payload = this.accountPayload(c, entries); String canonical = this.text(this.wire.canonicalize((JsonNode)payload)); String digest = OstrisWireCodec.sha256(this.wire.authorizationMessage((JsonNode)payload)); List existing = this.jdbc.query("select authorization_digest,status from ostris.transaction_proposal where id=? and tenant_id=?", (rs, n) -> new ProposalView(c.transactionId(), rs.getString(1), rs.getString(2)), new Object[]{c.transactionId(), c.tenantId()}); if (!existing.isEmpty()) {if (!((ProposalView)existing.getFirst()).authorizationDigest().equals(digest)) {throw new ProtocolException("TRANSACTION_ID_CONFLICT", "Transaction id already has different intent");} return (ProposalView)existing.getFirst();} this.jdbc.update("insert into ostris.transaction_proposal(id,tenant_id,community_id,unit_id,purpose,entries_json,references_json,contractual_metadata_digest,resolution_basis_type,resolution_basis_id,authorization_payload,authorization_digest) values(?,?,?,?,?,?::jsonb,?::jsonb,?,?,?,?,?)", new Object[]{c.transactionId(), c.tenantId(), c.communityId(), c.unitId(), c.purpose().name(), this.json(c.entries()), this.json(c.references()), c.contractualMetadataDigest(), c.resolutionBasisType() == null ? null : c.resolutionBasisType().name(), c.resolutionBasisId(), canonical, digest}); return new ProposalView(c.transactionId(), digest, "PROPOSED");}
@Transactional public void addAccountEvidence(UUID tenant, UUID proposal, UUID account, UUID credential, String signature) {Integer exact; Proposal p = this.load(tenant, proposal, false); if (p.purpose == TransactionPurpose.RESTITUTION && p.basisType != null) {throw new ProtocolException("RESTITUTION_AUTHORIZATION_PATH_MISMATCH", "Imposed RESTITUTION forbids AccountAuthorization");} if (p.purpose == TransactionPurpose.REVERSAL && p.basisType != null) {throw new ProtocolException("REVERSAL_AUTHORIZATION_PATH_MISMATCH", "Adjudicated REVERSAL forbids AccountAuthorization");} String key = (String)this.jdbc.queryForObject("select public_key_base64url from ostris.credential where id=? and tenant_id=?", String.class, new Object[]{credential, tenant}); String digest = OstrisWireCodec.sha256(this.wire.authorizationMessage(this.wire.parse(p.payload))); int inserted = this.jdbc.update("insert into ostris.authorization_evidence(id,tenant_id,community_id,proposal_id,account_id,credential_id,authorization_digest,signature_base64url,public_key_base64url) values(?,?,?,?,?,?,?,?,?) on conflict(proposal_id,account_id,credential_id) do nothing", new Object[]{UUID.randomUUID(), tenant, p.communityId, proposal, account, credential, digest, signature, key}); if (inserted == 0 && ((exact = (Integer)this.jdbc.queryForObject("select count(*) from ostris.authorization_evidence where tenant_id=? and proposal_id=? and account_id=? and credential_id=? and authorization_digest=? and signature_base64url=? and public_key_base64url=?", Integer.class, new Object[]{tenant, proposal, account, credential, digest, signature, key})) == null || exact != 1)) {throw new ProtocolException("EVIDENCE_CONFLICT", "Different evidence already exists for credential");}}
@Transactional public void addGovernanceEvidence(UUID tenant, UUID proposal, UUID authority, int version, ResolutionBasisType basisType, UUID basisId, Set<UUID> covered, UUID credential, String signature) {Integer exact; Proposal p = this.load(tenant, proposal, false); if (p.purpose == TransactionPurpose.REVERSAL && (p.basisType != ResolutionBasisType.FINAL_DISPUTE_RESOLUTION || p.basisType != basisType || !Objects.equals(p.basisId, basisId))) {throw new ProtocolException("REVERSAL_AUTHORIZATION_PATH_MISMATCH", "Governance basis must equal adjudicated REVERSAL proposal basis");} if (!(p.purpose != TransactionPurpose.RESTITUTION || p.basisType != null && p.basisType == basisType && Objects.equals(p.basisId, basisId))) {throw new ProtocolException("RESTITUTION_AUTHORIZATION_PATH_MISMATCH", "Governance basis must equal imposed RESTITUTION proposal basis");} if (p.purpose == TransactionPurpose.RESTITUTION && (Integer)this.jdbc.queryForObject("select count(*) from ostris.authorization_evidence where tenant_id=? and proposal_id=?", Integer.class, new Object[]{tenant, proposal}) > 0) {throw new ProtocolException("RESTITUTION_AUTHORIZATION_PATH_MISMATCH", "Mixed RESTITUTION evidence is forbidden");} List<TransactionEntry> entries = this.parseEntries(p.entriesJson); Set<UUID> affected = entries.stream().map(TransactionEntry::accountId).collect(Collectors.toSet()); GovernedAuthorizationRules.validate(p.purpose, basisType, affected, covered); ObjectNode payload = this.governancePayload(p, entries, authority, version, basisType, basisId, covered); String canonical = this.text(this.wire.canonicalize((JsonNode)payload)); String digest = OstrisWireCodec.sha256(this.wire.governanceAuthorizationMessage((JsonNode)payload)); String key = (String)this.jdbc.queryForObject("select public_key_base64url from ostris.credential where id=? and tenant_id=?", String.class, new Object[]{credential, tenant}); Integer knownBasis = (Integer)this.jdbc.queryForObject("select count(*) from ostris.resolution_basis where id=? and tenant_id=?", Integer.class, new Object[]{basisId, tenant}); if (knownBasis == null || knownBasis != 1) {throw new DataIntegrityViolationException("ResolutionBasis does not exist in tenant scope");} String coveredJson = this.json(covered.stream().sorted().map(UUID::toString).toList()); int inserted = this.jdbc.update("insert into ostris.governance_authorization_evidence(id,tenant_id,community_id,proposal_id,authority_id,authority_version,resolution_basis_id,resolution_basis_type,covered_accounts_json,credential_id,public_key_base64url,authorization_digest,signature_base64url,governance_payload) values(?,?,?,?,?,?,?,?,?::jsonb,?,?,?,?,?) on conflict(proposal_id,authority_id,credential_id) do nothing", new Object[]{UUID.randomUUID(), tenant, p.communityId, proposal, authority, version, basisId, basisType.name(), coveredJson, credential, key, digest, signature, canonical}); if (inserted == 0 && ((exact = (Integer)this.jdbc.queryForObject("select count(*) from ostris.governance_authorization_evidence where tenant_id=? and proposal_id=? and authority_id=? and credential_id=? and authority_version=? and resolution_basis_id=? and resolution_basis_type=? and covered_accounts_json=?::jsonb and public_key_base64url=? and authorization_digest=? and signature_base64url=? and governance_payload=?", Integer.class, new Object[]{tenant, proposal, authority, credential, version, basisId, basisType.name(), coveredJson, key, digest, signature, canonical})) == null || exact != 1)) {throw new ProtocolException("EVIDENCE_CONFLICT", "Different governance evidence already exists for credential");}}
@Transactional public CommitReceipt commit(UUID tenant, UUID proposalId) {Proposal p = this.load(tenant, proposalId, true); List committed = this.jdbc.query("select id,community_sequence,protocol_digest,committed_at from ostris.journal_transaction where id=? and tenant_id=?", (rs, n) -> new CommitReceipt(rs.getObject(1, UUID.class), rs.getLong(2), rs.getString(3), rs.getTimestamp(4).toInstant()), new Object[]{proposalId, tenant}); if (!committed.isEmpty()) {return (CommitReceipt)committed.getFirst();} CommunityEntity community = this.communities.lock(p.communityId, tenant).orElseThrow(() -> new ProtocolException("UNKNOWN_COMMUNITY", "Community not found")); long sequence = community.getNextSequence(); List<TransactionEntry> entries = this.parseEntries(p.entriesJson); this.revalidateProposalIntent(p, entries); this.validateRestitutionEvidencePath(p); Set<UUID> affected = entries.stream().map(TransactionEntry::accountId).collect(Collectors.toSet()); Set<UUID> governed = this.evaluateGovernance(p, sequence, affected, entries); if (Set.of(TransactionPurpose.PENALTY, TransactionPurpose.WRITE_OFF, TransactionPurpose.LOSS_OFFSET).contains((Object)p.purpose) && governed.isEmpty()) {throw new ProtocolException("MISSING_GOVERNANCE_AUTHORIZATION", "Purpose requires GovernanceAuthorization");} for (UUID account : affected) {if (governed.contains(account)) continue; this.evaluateAccount(p, sequence, account);} CommitTransactionCommand command = new CommitTransactionCommand(tenant, p.communityId, p.unitId, p.id, p.purpose, entries.stream().map(e -> new CommitTransactionCommand.Entry(e.accountId(), e.amount().wire())).toList(), this.parseMap(p.referencesJson), p.contractDigest, p.basisType, p.basisId); CommitReceipt receipt = this.journal.commit(command, governed); this.jdbc.update("update ostris.transaction_proposal set status='COMMITTED',committed_sequence=? where id=? and tenant_id=?", new Object[]{receipt.communitySequence(), p.id, tenant}); return receipt;}
private void evaluateAccount(Proposal p, long sequence, UUID account) {List policies = this.jdbc.query("select id,threshold from ostris.account_control_policy where tenant_id=? and account_id=? and activation_sequence<? and (superseded_sequence is null or superseded_sequence>?) order by policy_version desc limit 1", (rs, n) -> Map.entry(rs.getObject(1, UUID.class), rs.getInt(2)), new Object[]{p.tenantId, account, sequence, sequence}); if (policies.isEmpty()) {throw new ProtocolException("MISSING_CONTROL_POLICY", "No effective account control policy");} UUID policy = (UUID)((Map.Entry)policies.getFirst()).getKey(); int threshold = (Integer)((Map.Entry)policies.getFirst()).getValue(); HashSet<UUID> eligible = new HashSet<UUID>(this.jdbc.queryForList("select controller_id from ostris.account_controller where tenant_id=? and control_policy_id=?", UUID.class, new Object[]{p.tenantId, policy})); Set<UUID> signers = this.validControllers(p, sequence, "select e.credential_id,e.public_key_base64url,e.signature_base64url from ostris.authorization_evidence e where e.tenant_id=? and e.proposal_id=? and e.account_id=?", p.tenantId, p.id, account, false, null); ThresholdAuthorizationEvaluator.require(threshold, eligible, signers);}
private Set<UUID> evaluateGovernance(Proposal p, long sequence, Set<UUID> affected, List<TransactionEntry> entries) {List<GovRow> rows = this.jdbc.query("select authority_id,authority_version,resolution_basis_id,resolution_basis_type,covered_accounts_json::text,credential_id,public_key_base64url,signature_base64url,governance_payload from ostris.governance_authorization_evidence where tenant_id=? and proposal_id=?", (rs, n) -> new GovRow(rs.getObject(1, UUID.class), rs.getInt(2), rs.getObject(3, UUID.class), ResolutionBasisType.valueOf(rs.getString(4)), rs.getString(5), rs.getObject(6, UUID.class), rs.getString(7), rs.getString(8), rs.getString(9)), new Object[]{p.tenantId, p.id}); if (rows.isEmpty()) {return Set.of();} GovRow first = (GovRow)rows.getFirst(); if (rows.stream().anyMatch(r -> !r.sameIntent(first))) {throw new ProtocolException("INVALID_GOVERNANCE_EVIDENCE", "Governance evidence intents differ");} Set<UUID> covered = this.parseUuidSet(first.coveredJson); GovernedAuthorizationRules.validate(p.purpose, first.basisType, affected, covered); this.requireBasisReferenceBinding(p, first.basisType, first.basisId); Integer basis = (Integer)this.jdbc.queryForObject("select count(*) from ostris.resolution_basis where id=? and tenant_id=? and community_id=? and basis_type=? and status='FINAL' and finality_sequence<?", Integer.class, new Object[]{first.basisId, p.tenantId, p.communityId, first.basisType.name(), sequence}); if (basis == null || basis != 1) {throw new ProtocolException("RESOLUTION_BASIS_NOT_FINAL", "Resolution basis is not final/effective");} this.evaluateGovernedEconomicPolicy(p, sequence, first.basisType); List<Integer> authorities = this.jdbc.query("select threshold from ostris.community_resolution_authority where id=? and tenant_id=? and community_id=? and authority_version=? and activation_sequence<? and (revocation_sequence is null or revocation_sequence>?)", (rs, n) -> rs.getInt(1), new Object[]{first.authorityId, p.tenantId, p.communityId, first.version, sequence, sequence}); if (authorities.size() != 1) {throw new ProtocolException("AUTHORITY_NOT_EFFECTIVE", "Resolution authority not effective");} HashSet<UUID> eligible = new HashSet<UUID>(this.jdbc.queryForList("select controller_id from ostris.community_resolution_controller where tenant_id=? and authority_id=?", UUID.class, new Object[]{p.tenantId, first.authorityId})); HashSet<UUID> signers = new HashSet<UUID>(); for (GovRow row : rows) {JsonNode payload = this.wire.parse(row.payload); ObjectNode expected = this.governancePayload(p, entries, row.authorityId, row.version, row.basisType, row.basisId, covered); if (!Arrays.equals(this.wire.canonicalize(payload), this.wire.canonicalize((JsonNode)expected))) {throw new ProtocolException("INVALID_SIGNATURE", "Governance payload differs from proposal");} if (!Ed25519Authorization.verify(row.publicKey, row.signature, this.wire.governanceAuthorizationMessage((JsonNode)expected))) {throw new ProtocolException("INVALID_SIGNATURE", "Invalid governance signature");} signers.add(this.resolveController(p.tenantId, p.communityId, row.credentialId, row.publicKey, sequence));} ThresholdAuthorizationEvaluator.require((Integer)authorities.getFirst(), eligible, signers); return Set.copyOf(covered);}
private void requireBasisReferenceBinding(Proposal p, ResolutionBasisType type, UUID basisId) {Map<String, String> refs = this.parseMap(p.referencesJson); String field = switch (type) {case FINAL_FINDING -> "finalFindingId"; case FINAL_DEFAULT_DECISION -> "defaultDecisionId"; case COMMUNITY_GOVERNANCE_DECISION -> "governanceDecisionId"; case FINAL_DISPUTE_RESOLUTION -> null;}; if (p.purpose == TransactionPurpose.RESTITUTION) {if (!Objects.equals((Object)p.basisType, (Object)type) || !Objects.equals(p.basisId, basisId)) {throw new ProtocolException("RESOLUTION_BASIS_REFERENCE_MISMATCH", "Restitution basis differs from signed proposal");} return;} if (field != null && !Objects.equals(refs.get(field), basisId.toString())) {throw new ProtocolException("RESOLUTION_BASIS_REFERENCE_MISMATCH", "Governance basis differs from typed transaction reference");}}
private void evaluateGovernedEconomicPolicy(Proposal p, long sequence, ResolutionBasisType basis) {String type = switch (p.purpose) {case PENALTY, RESTITUTION -> "SANCTION"; case WRITE_OFF -> "DEFAULT"; default -> null;}; if (type == null) {return;} List configs = this.jdbc.queryForList("select config_json::text from ostris.policy_version where tenant_id=? and community_id=? and policy_type=? and activation_sequence<? and (superseded_sequence is null or superseded_sequence>?) order by policy_version desc limit 1", String.class, new Object[]{p.tenantId, p.communityId, type, sequence, sequence}); if (configs.size() != 1) {throw new ProtocolException("MISSING_GOVERNED_ECONOMIC_POLICY", "No effective governed economic policy");} try {GovernedEconomicPolicyEvaluator.require(p.purpose, basis, this.mapper.readTree((String)configs.getFirst()));} catch (ProtocolException ex) {throw ex;} catch (Exception ex) {throw new ProtocolException("INVALID_GOVERNED_ECONOMIC_POLICY", "Policy config is not valid JSON");}}
private Set<UUID> validControllers(Proposal p, long sequence, String sql, Object a, Object b, Object c, boolean governance, Object unused) {HashSet<UUID> result = new HashSet<UUID>(); for (Sig row : this.jdbc.query(sql, (rs, n) -> new Sig(rs.getObject(1, UUID.class), rs.getString(2), rs.getString(3)), new Object[]{a, b, c})) {if (!Ed25519Authorization.verify(row.key, row.signature, this.wire.authorizationMessage(this.wire.parse(p.payload)))) {throw new ProtocolException("INVALID_SIGNATURE", "Invalid account signature");} result.add(this.resolveController(p.tenantId, p.communityId, row.credential, row.key, sequence));} return result;}
private UUID resolveController(UUID tenant, UUID community, UUID credential, String key, long sequence) {List rows = this.jdbc.queryForList("select b.controller_id from ostris.controller_credential_binding b join ostris.credential c on c.id=b.credential_id join ostris.protocol_controller pc on pc.id=b.controller_id where b.tenant_id=? and b.community_id=? and b.credential_id=? and b.public_key_base64url=? and c.public_key_base64url=? and c.activation_sequence<? and (c.revocation_sequence is null or c.revocation_sequence>?) and b.activation_sequence<? and (b.revocation_sequence is null or b.revocation_sequence>?) and pc.activation_sequence<? and (pc.revocation_sequence is null or pc.revocation_sequence>?)", UUID.class, new Object[]{tenant, community, credential, key, key, sequence, sequence, sequence, sequence, sequence, sequence}); if (rows.size() != 1) {throw new ProtocolException("CREDENTIAL_NOT_ELIGIBLE", "Credential/controller binding is not uniquely active");} return (UUID)rows.getFirst();}
private Proposal load(UUID tenant, UUID id, boolean lock) {String suffix = lock ? " for update" : ""; return (Proposal)this.jdbc.query("select id,tenant_id,community_id,unit_id,purpose,entries_json::text,references_json::text,contractual_metadata_digest,resolution_basis_type,resolution_basis_id,authorization_payload,status from ostris.transaction_proposal where id=? and tenant_id=?" + suffix, (rs, n) -> new Proposal(rs.getObject(1, UUID.class), rs.getObject(2, UUID.class), rs.getObject(3, UUID.class), rs.getObject(4, UUID.class), TransactionPurpose.valueOf(rs.getString(5)), rs.getString(6), rs.getString(7), rs.getString(8), rs.getString(9) == null ? null : ResolutionBasisType.valueOf(rs.getString(9)), rs.getObject(10, UUID.class), rs.getString(11), rs.getString(12)), new Object[]{id, tenant}).stream().findFirst().orElseThrow(() -> new ProtocolException("UNKNOWN_PROPOSAL", "Proposal not found"));}
private List<TransactionEntry> entries(CommitTransactionCommand c) {return c.entries().stream().map(e -> new TransactionEntry(e.accountId(), OstrisAmount.parse(e.amount()))).toList();}
private void validateRestitutionProposal(CommitTransactionCommand c) {String forbidden; if (c.purpose() != TransactionPurpose.RESTITUTION) {return;} boolean finding = c.references().containsKey("finalFindingId"); boolean dispute = c.references().containsKey("disputeResolutionId"); if (c.resolutionBasisType() == null) {if (c.resolutionBasisId() != null || finding || dispute) {throw new ProtocolException("INVALID_RESTITUTION_REFERENCE", "Voluntary RESTITUTION forbids mandate basis/references");} return;} if (c.resolutionBasisId() == null || !Set.of(ResolutionBasisType.FINAL_FINDING, ResolutionBasisType.FINAL_DISPUTE_RESOLUTION).contains((Object)c.resolutionBasisType()) || finding == dispute) {throw new ProtocolException("INVALID_RESTITUTION_REFERENCE", "Imposed RESTITUTION requires exactly one allowed typed basis/reference");} String field = c.resolutionBasisType() == ResolutionBasisType.FINAL_FINDING ? "finalFindingId" : "disputeResolutionId"; String string = forbidden = c.resolutionBasisType() == ResolutionBasisType.FINAL_FINDING ? "disputeResolutionId" : "finalFindingId"; if (c.references().containsKey(forbidden) || !Objects.equals(c.references().get(field), c.resolutionBasisId().toString())) {throw new ProtocolException("INVALID_RESTITUTION_REFERENCE", "Typed reference must equal ResolutionBasis id");} UuidV7.parse(c.references().get(field)); UuidV7.parse(c.resolutionBasisId().toString());}
private void validateRestitutionEvidencePath(Proposal p) {if (p.purpose != TransactionPurpose.RESTITUTION) {return;} Integer accounts = (Integer)this.jdbc.queryForObject("select count(*) from ostris.authorization_evidence where tenant_id=? and proposal_id=?", Integer.class, new Object[]{p.tenantId, p.id}); Integer governance = (Integer)this.jdbc.queryForObject("select count(*) from ostris.governance_authorization_evidence where tenant_id=? and proposal_id=?", Integer.class, new Object[]{p.tenantId, p.id}); if (p.basisType == null) {if (governance != null && governance > 0) {throw new ProtocolException("RESTITUTION_AUTHORIZATION_PATH_MISMATCH", "Voluntary RESTITUTION forbids GovernanceAuthorization");}} else {if (accounts != null && accounts > 0) {throw new ProtocolException("RESTITUTION_AUTHORIZATION_PATH_MISMATCH", "Imposed RESTITUTION forbids AccountAuthorization");} if (governance == null || governance == 0) {throw new ProtocolException("RESTITUTION_AUTHORIZATION_PATH_MISMATCH", "Imposed RESTITUTION requires GovernanceAuthorization");}}}
private void revalidateProposalIntent(Proposal p, List<TransactionEntry> entries) {byte[] stored; CommitTransactionCommand reconstructed = new CommitTransactionCommand(p.tenantId, p.communityId, p.unitId, p.id, p.purpose, entries.stream().map(e -> new CommitTransactionCommand.Entry(e.accountId(), e.amount().wire())).toList(), this.parseMap(p.referencesJson), p.contractDigest, p.basisType, p.basisId); byte[] expected = this.wire.canonicalize((JsonNode)this.accountPayload(reconstructed, entries)); if (!Arrays.equals(expected, stored = this.wire.canonicalize(this.wire.parse(p.payload)))) {throw new ProtocolException("PROPOSAL_INTENT_MISMATCH", "Stored proposal intent is not canonical or differs from economic fields");}}
private List<TransactionEntry> parseEntries(String json) {try {JsonNode n = this.mapper.readTree(json); ArrayList<TransactionEntry> out = new ArrayList<TransactionEntry>(); for (JsonNode e : n) {out.add(new TransactionEntry(UUID.fromString(e.path("accountId").asText()), OstrisAmount.parse(e.path("amount").asText())));} return out;} catch (Exception e) {throw new ProtocolException("INVALID_PROPOSAL", e.getMessage());}}
private Map<String, String> parseMap(String json) {try {return (Map)this.mapper.readValue(json, (JavaType)this.mapper.getTypeFactory().constructMapType(Map.class, String.class, String.class));} catch (Exception e) {throw new ProtocolException("INVALID_PROPOSAL", e.getMessage());}}
private ObjectNode accountPayload(CommitTransactionCommand c, List<TransactionEntry> entries) {ObjectNode n = this.base(c.communityId(), c.unitId(), c.transactionId(), c.purpose(), entries, c.references()); if (c.contractualMetadataDigest() != null) {n.put("contractualMetadataDigest", c.contractualMetadataDigest());} if (c.resolutionBasisType() != null) {ObjectNode rb = n.putObject("resolutionBasis"); rb.put("id", c.resolutionBasisId().toString()); rb.put("type", c.resolutionBasisType().name());} return n;}
private ObjectNode governancePayload(Proposal p, List<TransactionEntry> entries, UUID authority, int version, ResolutionBasisType type, UUID basis, Set<UUID> covered) {ObjectNode n = this.base(p.communityId, p.unitId, p.id, p.purpose, entries, this.parseMap(p.referencesJson)); n.put("authorityId", authority.toString()); n.put("authorityPolicyVersion", version); ArrayNode ca = n.putArray("coveredAccounts"); covered.stream().sorted().forEach(id -> ca.add(id.toString())); ObjectNode rb = n.putObject("resolutionBasis"); rb.put("id", basis.toString()); rb.put("type", type.name()); return n;}
private ObjectNode base(UUID community, UUID unit, UUID tx, TransactionPurpose purpose, List<TransactionEntry> entries, Map<String, String> refs) {ObjectNode n = this.mapper.createObjectNode(); n.put("communityId", community.toString()); ArrayNode a = n.putArray("entries"); for (TransactionEntry e : entries) {ObjectNode x = a.addObject(); x.put("accountId", e.accountId().toString()); x.put("amount", e.amount().wire());} n.put("ostrisCoreVersion", "0.1"); n.put("purpose", purpose.name()); ObjectNode r = n.putObject("references"); refs.forEach((arg_0, arg_1) -> ((ObjectNode)r).put(arg_0, arg_1)); n.put("transactionId", tx.toString()); n.put("unitId", unit.toString()); n.put("wireFormat", "OSTRIS-CORE-JCS-1"); return n;}
private Set<UUID> parseUuidSet(String json) {try {HashSet<UUID> s = new HashSet<UUID>(); for (JsonNode n : this.mapper.readTree(json)) {s.add(UUID.fromString(n.asText()));} return s;} catch (Exception e) {throw new ProtocolException("INVALID_COVERED_ACCOUNTS", e.getMessage());}}
private String json(Object o) {try {return this.mapper.writeValueAsString(o);} catch (Exception e) {throw new IllegalStateException(e);}}
private String text(byte[] b) {return new String(b, StandardCharsets.UTF_8);}
public record ProposalView(UUID transactionId, String authorizationDigest, String status) {}
private record Proposal(UUID id, UUID tenantId, UUID communityId, UUID unitId, TransactionPurpose purpose, String entriesJson, String referencesJson, String contractDigest, ResolutionBasisType basisType, UUID basisId, String payload, String status) {}
private record GovRow(UUID authorityId, int version, UUID basisId, ResolutionBasisType basisType, String coveredJson, UUID credentialId, String publicKey, String signature, String payload) {boolean sameIntent(GovRow o) {return this.authorityId.equals(o.authorityId) && this.version == o.version && this.basisId.equals(o.basisId) && this.basisType == o.basisType && this.coveredJson.equals(o.coveredJson) && this.payload.equals(o.payload);}}
private record Sig(UUID credential, String key, String signature) {}
}
